import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { UserCaseData } from '../../interfaces/userdashboard.interface';
import { ErrorHandlerUtil } from '../../utility/error-handler.util';

@Injectable({
  providedIn: 'root'
})
export class UserdashboardService {
  private readonly dashboardCache = new Map<number, Promise<UserCaseData[]>>();
  private readonly cacheTimestamps = new Map<number, number>();
  private readonly cacheExpiryMs = (environment as any).cacheExpiryMs || (60 * 60 * 1000);

  constructor(private readonly http: HttpClient) {
  }

  async getDashboardlist(pageNumber: number): Promise<UserCaseData[]> {
    const now = Date.now();
    const cachedTimestamp = this.cacheTimestamps.get(pageNumber);

    // Return cached result if still valid
    if (this.dashboardCache.has(pageNumber) && cachedTimestamp && now - cachedTimestamp < this.cacheExpiryMs) {
      return this.dashboardCache.get(pageNumber) ?? Promise.reject(new Error('Cache entry not found'));
    }

    // Create new request and cache it
    const params = new HttpParams().set('pageNumber', pageNumber);
    const resultPromise = (async () => {
      try {
        const response = await firstValueFrom(
          this.http.get<any>(
            `${environment.cloudUrl}${environment.coreservice}/user-dashboard/caselist`,
            { params }
          )
        );
        return this.arrangeDashboardData(response);
      } catch (error) {
        // Clear cache on error
        this.dashboardCache.delete(pageNumber);
        this.cacheTimestamps.delete(pageNumber);
        throw new Error(`Error fetching dashboard list: ${ErrorHandlerUtil.getErrorMessage(error)}`);
      }
    })();

    // Store in cache
    this.dashboardCache.set(pageNumber, resultPromise);
    this.cacheTimestamps.set(pageNumber, now);

    return resultPromise;
  }

  invalidateCache(): void {
    this.dashboardCache.clear();
    this.cacheTimestamps.clear();
  }

  async getDashInfo(): Promise<any[]> {
    try {
      return await firstValueFrom(
        this.http.get<any[]>(
          `${environment.cloudUrl}${environment.coreservice}/user-dashboard/dashinfo`
        )
      );
    } catch (error) {
      throw new Error(`Error fetching dashboard info: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  private arrangeDashboardData(response: any): UserCaseData[] {
    if (response?.length !== 3) {
      return [];
    }
    const caseList = response[0] as UserCaseData[];
    for (const team of response[1]) {
      team.users = response[2].filter((user: any) => user.teams.includes(team.nTeamid));
    }
    for (const caseItem of caseList) {
      caseItem.teams = response[1].filter((team: any) => team.nCaseid === caseItem.nCaseid);
    }
    return caseList;
  }
}